def solve(gi):
    cnt={}
    for v in gi.flat: cnt[v]=cnt.get(v,0)+1
    bg=max(cnt,key=cnt.get); mk=[v for v in cnt if v!=bg][0]
    h,w=gi.shape
    marks=gi==mk
    vis=np.zeros_like(marks,dtype=bool)
    Q=collections.deque()
    for r in range(h):
        for c in [0,w-1]:
            if not marks[r,c] and not vis[r,c]: vis[r,c]=True; Q.append((r,c))
    for c in range(w):
        for r in [0,h-1]:
            if not marks[r,c] and not vis[r,c]: vis[r,c]=True; Q.append((r,c))
    while Q:
        r,c=Q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and not marks[nr,nc] and not vis[nr,nc]:
                vis[nr,nc]=True; Q.append((nr,nc))
    pred = (~marks) & ~vis
    return (pred*(go==2)+marks).astype(int)

